// Flattens the config table into one object so later nodes can read settings
// as $('Config').first().json.SLOTS instead of searching rows.
// Defaults are applied for any key missing from the table, so the workflow
// still runs on a fresh install. Mode: Run Once for All Items.

const DEFAULTS = {
  TIMEZONE: 'Europe/Belgrade',
  SLOTS: '10:00,15:00,20:00',
  TEXT_MODE: 'pinterest',
  REPOST_AFTER_DAYS: '60',
  SCHEDULE_HORIZON_DAYS: '14',
  MAX_QUEUE_PER_RUN: '60',
  RETRY_DELAY_MINUTES: '30',
  EXTRA_HASHTAGS: '',
  POST_TEXT_MAX_CHARS: '600',
  FB_PAGE_ID: '',
  PIN_RESOLVE_MAX_PER_RUN: '10',
  RESOLVE_THROTTLE_MS: '2000',
  RESOLVE_MAX_ATTEMPTS: '3',
  DRY_RUN: 'true',
  MAX_PUBLISH_PER_RUN: '20',
  FB_API_VERSION: 'v21.0',
  AUTH_MODE: 'oauth',
};

const cfg = { ...DEFAULTS };
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.key) cfg[String(r.key)] = r.value == null ? '' : String(r.value);
}

// Typed views, so consumers never re-parse strings.
cfg._slots = String(cfg.SLOTS).split(',').map((s) => s.trim()).filter(Boolean);
cfg._repost_after_days = Number(cfg.REPOST_AFTER_DAYS) || 0;
cfg._resolve_max = Math.max(1, Number(cfg.PIN_RESOLVE_MAX_PER_RUN) || 10);
cfg._throttle_ms = Math.max(0, Number(cfg.RESOLVE_THROTTLE_MS) || 0);
cfg._resolve_max_attempts = Math.max(1, Number(cfg.RESOLVE_MAX_ATTEMPTS) || 3);
cfg._horizon_days = Math.max(1, Number(cfg.SCHEDULE_HORIZON_DAYS) || 14);
cfg._max_queue = Math.max(1, Number(cfg.MAX_QUEUE_PER_RUN) || 60);
cfg._text_max = Math.max(80, Number(cfg.POST_TEXT_MAX_CHARS) || 600);
cfg._retry_delay_minutes = Math.max(1, Number(cfg.RETRY_DELAY_MINUTES) || 30);
cfg._max_publish = Math.max(1, Number(cfg.MAX_PUBLISH_PER_RUN) || 20);
// Anything but an explicit "false" keeps the safety on.
cfg._dry_run = String(cfg.DRY_RUN).trim().toLowerCase() !== 'false';
// Anything other than an explicit "token" means the OAuth login path.
cfg._auth_mode = String(cfg.AUTH_MODE).trim().toLowerCase() === 'token'
  ? 'token' : 'oauth';

return [{ json: cfg }];

// Normalizes the boards table into sync work items.
//
// Every board is synced whether or not it is enabled - `enabled` controls
// PUBLISHING (Workflow B), not collection. We keep accumulating pins for
// disabled boards so that enabling one later has a backlog ready.
// Mode: Run Once for All Items.

const rows = $input.all().map((i) => i.json || {}).filter((r) => r.board_slug || r.rss_url);
const now = new Date().toISOString();

const valid = [];
const bad = [];

for (const r of rows) {
  const slug = String(r.board_slug || '').trim();
  const url = String(r.rss_url || '').trim();
  if (!slug || !/^https?:\/\//i.test(url)) {
    bad.push({ slug, url });
    continue;
  }
  valid.push({
    row_id: r.id,
    board_slug: slug,
    name: String(r.name || slug),
    rss_url: url,
    enabled: r.enabled === true,
    priority: Number(r.priority) || 0,
  });
}

if (!valid.length) {
  return [{ json: {
    _kind: 'log',
    workflow: 'A - Sync Boards',
    level: 'warn',
    context: 'load_boards',
    message: rows.length
      ? `No usable boards. ${bad.length} row(s) lack a slug or a valid rss_url.`
      : 'The boards table is empty. Add a board via Workflow D or the table UI.',
    created_at: now,
  } }];
}

// Highest priority first, so a run that hits a cap does the important boards.
valid.sort((a, b) => b.priority - a.priority || a.board_slug.localeCompare(b.board_slug));
return valid.map((b) => ({ json: { _kind: 'board', ...b } }));

// Passthrough for the board currently being iterated.
//
// Exists so downstream nodes can reference ONE stable, single-item
// node instead of $('Loop Boards'), which does not resolve from
// branches that sit behind a data-table write (item lineage is lost
// there, and .first() returns undefined).
// Mode: Run Once for All Items.

const b = $input.first().json;
return [{ json: { ...b, last_synced_at: new Date().toISOString() } }];

/**
 * Pinterest pin -> Etsy listing extraction.
 *
 * This is the ONLY place that knows Pinterest exists. It is kept as a plain
 * module so it can be unit-tested outside n8n; the same body is pasted into
 * Workflow A's "Parse Pins" Code node.
 *
 * Contract (the isolation boundary the rest of the system depends on):
 *   input : a raw RSS item object from the RSS Feed Read node
 *   output: { ok: true, etsy_listing_id, etsy_url, title, description,
 *             image_url, image_candidates, pin_url }
 *        or { ok: false, reason, pin_url }
 *
 * Workflows B/C/D never see a field from this file other than the ones above,
 * and key off etsy_listing_id. Swapping in the Etsy API later means replacing
 * this file and nothing else.
 */

// ---------------------------------------------------------------- HTML text

const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  hellip: '…', mdash: '—', ndash: '–', rsquo: '’',
  lsquo: '‘', ldquo: '“', rdquo: '”', middot: '·',
  eacute: 'é', trade: '™', reg: '®', copy: '©',
};

function decodeEntities(s) {
  return String(s || '')
    .replace(/&#x([0-9a-f]+);/gi, (_, h) => safeCodePoint(parseInt(h, 16)))
    .replace(/&#(\d+);/g, (_, d) => safeCodePoint(parseInt(d, 10)))
    .replace(/&([a-z]+);/gi, (m, name) => {
      const k = name.toLowerCase();
      return Object.prototype.hasOwnProperty.call(ENTITIES, k) ? ENTITIES[k] : m;
    });
}

function safeCodePoint(n) {
  if (!Number.isFinite(n) || n < 0 || n > 0x10ffff) return '';
  try { return String.fromCodePoint(n); } catch { return ''; }
}

// Pinterest boilerplate that adds nothing to a Facebook caption.
const BOILERPLATE = [
  /\b(?:this|these)\s+pins?\s+(?:was|were)\s+discovered\s+by[^.]*\.?/i,
  /\bdiscover\s+\(and\s+save!?\)\s+your\s+own\s+pins\s+on\s+pinterest\.?/i,
  /\bfind\s+this\s+pin\s+and\s+more\s+on\s+[^.|]*\s+by\s+[^.|]*\.?/i,
  /\bsaved?\s+(from|to)\s+pinterest\.?/i,
  /\bmore\s+ideas\s+about\s+[^.]*\./i,
  /\bclick\s+(the\s+)?link\s+(in\s+bio|to\s+(shop|buy|view))\b[^.]*\.?/i,
  /\bvisit\s+(my|our)\s+(etsy\s+)?shop\s+for\s+more\b[^.]*\.?/i,
];

/** Strip tags, decode entities, drop boilerplate, collapse whitespace. */
function cleanText(html) {
  let s = String(html == null ? '' : html);
  s = s.replace(/<script[\s\S]*?<\/script>/gi, ' ')
       .replace(/<style[\s\S]*?<\/style>/gi, ' ');
  // Keep paragraph/line structure before tags are removed.
  s = s.replace(/<br\s*\/?>/gi, '\n').replace(/<\/p>/gi, '\n\n');
  s = s.replace(/<[^>]*>/g, ' ');
  s = decodeEntities(s);
  // A bare Pinterest/Etsy URL left in the body is noise; the link is appended
  // deliberately at the end of the caption by Workflow B.
  s = s.replace(/https?:\/\/(www\.)?(pinterest\.[a-z.]+|pin\.it|etsy\.com)\/\S*/gi, ' ');
  for (const re of BOILERPLATE) s = s.replace(re, ' ');
  s = s.replace(/[ \t ]+/g, ' ')
       .replace(/ ?\n ?/g, '\n')
       .replace(/\n{3,}/g, '\n\n')
       .trim();
  return s;
}

// ---------------------------------------------------------------- Etsy link

/**
 * Etsy listing URLs we accept:
 *   https://www.etsy.com/listing/1234567890/slug?utm_source=...
 *   https://etsy.com/listing/1234567890
 *   https://www.etsy.com/il-en/listing/1234567890/slug   (locale prefix)
 *   https://www.etsy.com/shop/X/listing/1234567890/slug
 * Rejected: anything without a /listing/{digits} segment.
 */
const ETSY_LISTING_RE = /https?:\/\/(?:[a-z0-9-]+\.)?etsy\.com\/(?:[a-z]{2}-[a-z]{2}\/)?(?:[^\s"'<>?#]*\/)?listing\/(\d{6,15})(?:[\/?#][^\s"'<>]*)?/i;

/** Pinterest wraps outbound links in a redirector; unwrap before matching. */
function unwrapRedirect(url) {
  const s = String(url || '');
  const m = s.match(/[?&](?:url|u|redirect|target|dest)=([^&]+)/i);
  if (!m) return s;
  try {
    const inner = decodeURIComponent(m[1]);
    if (/^https?:\/\//i.test(inner)) return inner;
  } catch { /* malformed escape - fall through */ }
  return s;
}

/** Collect every plausible URL from an RSS item, in order of trustworthiness. */
function linkCandidates(item) {
  const out = [];
  const push = (v) => { if (v && typeof v === 'string') out.push(v); };

  push(item.link);
  push(item.guid && (item.guid._ || item.guid.value || item.guid));
  push(item.id);
  // Some feeds put the outbound URL in an enclosure or a namespaced field.
  if (item.enclosure && item.enclosure.url) push(item.enclosure.url);
  push(item['pinterest:link']);

  const html = [
    item.description,
    item.content,
    item['content:encoded'],
    item.contentSnippet,
    item.summary,
  ].filter(Boolean).join(' ');

  // Every href/src in the HTML, plus any bare URL in the text.
  for (const m of html.matchAll(/(?:href|src)\s*=\s*["']([^"']+)["']/gi)) push(m[1]);
  for (const m of html.matchAll(/https?:\/\/[^\s"'<>)]+/gi)) push(m[0]);

  return out.map(unwrapRedirect);
}

/** First Etsy listing link found, normalized. null when the pin has none. */
function extractEtsy(item) {
  for (const cand of linkCandidates(item)) {
    const m = String(cand).match(ETSY_LISTING_RE);
    if (m) {
      const id = m[1];
      return { etsy_listing_id: id, etsy_url: `https://www.etsy.com/listing/${id}` };
    }
  }
  return null;
}

// ------------------------------------------------------------------- images

/**
 * Pinterest serves the same image at several sizes under a size segment:
 *   https://i.pinimg.com/236x/ab/cd/ef/abcdef123.jpg
 *   https://i.pinimg.com/originals/ab/cd/ef/abcdef123.jpg
 * /originals/ is the largest but does not always exist (and can carry a
 * different extension), so return an ordered candidate list. Workflow A
 * HEAD-checks them and stores the first that actually loads.
 */
const PINIMG_SIZE_RE = /^(https?:\/\/i\.pinimg\.com\/)([^/]+)(\/.+)$/i;
const SIZE_PREFERENCE = ['originals', '1200x', '736x', '564x', '474x', '236x'];

function imageCandidates(url) {
  const s = String(url || '').trim();
  if (!s) return [];
  const m = s.match(PINIMG_SIZE_RE);
  if (!m) return [s];
  const [, host, currentSize, path] = m;
  const out = [];
  for (const size of SIZE_PREFERENCE) {
    out.push(`${host}${size}${path}`);
    // /originals/ frequently stores a .png or .webp where the thumb was .jpg.
    if (size === 'originals') {
      const swapped = path.replace(/\.(jpe?g)$/i, '.png');
      if (swapped !== path) out.push(`${host}${size}${swapped}`);
    }
  }
  if (!SIZE_PREFERENCE.includes(currentSize.toLowerCase())) out.push(s);
  // De-duplicate, preserve order, and always keep the original as last resort.
  const seen = new Set();
  const uniq = out.filter((u) => !seen.has(u) && seen.add(u));
  if (!uniq.includes(s)) uniq.push(s);
  return uniq;
}

/** Pull the pin image out of an RSS item. */
function extractImage(item) {
  const html = [
    item.description, item.content, item['content:encoded'], item.summary,
  ].filter(Boolean).join(' ');

  // Prefer a real media field when the feed provides one.
  const media = item['media:content'] || item['media:thumbnail'];
  const mediaUrl = media && (media.url || (media.$ && media.$.url));
  if (mediaUrl) return String(mediaUrl);
  if (item.enclosure && item.enclosure.url && /^image\//i.test(item.enclosure.type || 'image/')) {
    return String(item.enclosure.url);
  }

  const img = html.match(/<img[^>]+src\s*=\s*["']([^"']+)["']/i);
  if (img) return img[1];
  const bare = html.match(/https?:\/\/i\.pinimg\.com\/[^\s"'<>)]+\.(?:jpe?g|png|webp)/i);
  return bare ? bare[0] : '';
}

/** The pin's own Pinterest URL, for the pin_urls audit trail. */
function extractPinUrl(item) {
  const cands = [
    item.guid && (item.guid._ || item.guid.value || item.guid),
    item.link,
    item.id,
  ].filter((v) => typeof v === 'string');
  for (const c of cands) {
    const m = c.match(/https?:\/\/(?:[a-z0-9-]+\.)?pinterest\.[a-z.]+\/pin\/\d+/i);
    if (m) return m[0];
  }
  const html = [item.description, item.content, item['content:encoded']]
    .filter(Boolean).join(' ');
  const m = html.match(/https?:\/\/(?:[a-z0-9-]+\.)?pinterest\.[a-z.]+\/pin\/\d+/i);
  return m ? m[0] : '';
}

// ------------------------------------------------------------------- public

function parsePin(item, opts = {}) {
  const pin_url = extractPinUrl(item);
  const etsy = extractEtsy(item);
  if (!etsy) {
    return { ok: false, reason: 'no_etsy_link', pin_url,
             title: cleanText(item.title).slice(0, 120) };
  }
  const rawImage = extractImage(item);
  const cands = imageCandidates(rawImage);
  const title = cleanText(item.title);
  const description = cleanText(
    item.description || item.content || item['content:encoded'] || item.summary || ''
  );
  if (!cands.length) {
    return { ok: false, reason: 'no_image', pin_url, title,
             etsy_listing_id: etsy.etsy_listing_id };
  }
  return {
    ok: true,
    etsy_listing_id: etsy.etsy_listing_id,
    etsy_url: etsy.etsy_url,
    title,
    description,
    image_url: cands[0],          // provisional; HEAD-verified downstream
    image_candidates: cands,
    pin_url,
    board_slug: opts.board_slug || '',
  };
}

// ---------------------------------------------------------------- n8n glue
// Turns one board's RSS items into `pins` rows plus log rows.
//
// Note: a pin row is written even when the feed carries no Etsy link, because
// Pinterest's RSS never does - the link is recovered from the pin page in
// phase 2. resolve_status='new' marks a pin as awaiting that step.
// Mode: Run Once for All Items.

const board = $('Current Board').first().json;
const board_slug = board.board_slug;
const rss_url = board.rss_url;
const now = new Date().toISOString();

const rows = [];
const rejected = {};
let total = 0;
let feedError = null;

for (const item of $input.all()) {
  const raw = item.json || {};

  // The RSS node continues on error so one dead board cannot stop the rest;
  // a failed fetch arrives as an item carrying .error.
  if (raw.error) {
    feedError = String(raw.error.message || raw.error);
    break;
  }
  // alwaysOutputData can emit one empty placeholder item.
  if (!raw.title && !raw.link && !raw.guid && !raw.content) continue;

  total++;
  const r = parsePin(raw, { board_slug });
  const pin_url = r.pin_url || extractPinUrl(raw);
  const pin_id = (String(pin_url).match(/\/pin\/(\d+)/) || [])[1] || '';

  if (!pin_id) { rejected.no_pin_id = (rejected.no_pin_id || 0) + 1; continue; }

  const cands = r.ok && r.image_candidates.length
    ? r.image_candidates
    : imageCandidates(extractImage(raw));
  if (!cands.length) { rejected.no_image = (rejected.no_image || 0) + 1; continue; }

  rows.push({ json: {
    _kind: 'pin',
    pin_id,
    pin_url,
    board_slug,
    title: r.ok ? r.title : cleanText(raw.title),
    description: r.ok ? r.description
      : cleanText(raw.description || raw.content || raw['content:encoded'] || ''),
    image_url: cands[0],
    image_candidates: JSON.stringify(cands),
    // A feed that *does* carry the link skips the resolve step entirely.
    etsy_listing_id: r.ok ? r.etsy_listing_id : '',
    resolve_status: r.ok ? 'ok' : 'new',
    resolve_error: '',
    resolve_attempts: 0,
    first_seen_at: now,
    resolved_at: r.ok ? now : null,
  } });
}

if (feedError) {
  return [{ json: {
    _kind: 'log',
    workflow: 'A - Sync Boards',
    level: 'error',
    context: `board=${board_slug} url=${rss_url}`,
    message: `Feed fetch failed: ${feedError}`,
    created_at: now,
  } }];
}

const summary = {
  _kind: 'log',
  workflow: 'A - Sync Boards',
  level: rows.length ? 'info' : 'warn',
  context: `board=${board_slug}`,
  message: `feed_items=${total} usable_pins=${rows.length}`
    + (Object.keys(rejected).length ? ` rejected=${JSON.stringify(rejected)}` : ''),
  created_at: now,
};

return rows.length ? [...rows, { json: summary }] : [{ json: summary }];

// Phase 2 gate: decide which pins get their page fetched this run.
//
// Each pin page is ~1MB, so this is the throttle that keeps a sync from
// turning into a scrape. Only pins with resolve_status='new' are candidates;
// 'ok', 'not_etsy' and 'failed' are terminal. Mode: Run Once for All Items.

const cfg = $('Config').first().json;
const rows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => r.pin_id && r.resolve_status === 'new');

if (!rows.length) {
  return [{ json: { _kind: 'none',
    message: 'No pins awaiting resolution - every known pin is already '
           + 'resolved, parked as not_etsy, or failed past its retry limit.' } }];
}

// Oldest first, so a backlog drains in the order pins were discovered.
rows.sort((a, b) => String(a.first_seen_at || '').localeCompare(String(b.first_seen_at || '')));

return rows.slice(0, cfg._resolve_max).map((r) => ({ json: {
  pin_id: String(r.pin_id),
  pin_url: String(r.pin_url || ''),
  board_slug: String(r.board_slug || ''),
  title: String(r.title || ''),
  description: String(r.description || ''),
  image_url: String(r.image_url || ''),
  image_candidates: r.image_candidates || '[]',
  resolve_attempts: Number(r.resolve_attempts) || 0,
  resolved_at: r.resolved_at || null,
  etsy_listing_id: String(r.etsy_listing_id || ''),
} }));

/**
 * Pinterest pin -> Etsy listing extraction.
 *
 * This is the ONLY place that knows Pinterest exists. It is kept as a plain
 * module so it can be unit-tested outside n8n; the same body is pasted into
 * Workflow A's "Parse Pins" Code node.
 *
 * Contract (the isolation boundary the rest of the system depends on):
 *   input : a raw RSS item object from the RSS Feed Read node
 *   output: { ok: true, etsy_listing_id, etsy_url, title, description,
 *             image_url, image_candidates, pin_url }
 *        or { ok: false, reason, pin_url }
 *
 * Workflows B/C/D never see a field from this file other than the ones above,
 * and key off etsy_listing_id. Swapping in the Etsy API later means replacing
 * this file and nothing else.
 */

// ---------------------------------------------------------------- HTML text

const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  hellip: '…', mdash: '—', ndash: '–', rsquo: '’',
